""" Create json file that is compatible with autocorrection script and to upload it to netact """

import json
import re
import subprocess
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class DeltaFileConverter:

    def __init__(self):
        self.input_file = "delta.json"
        self.ac_output_file = ""
        self.nt_output_file = ""
        self.nidd_file = ""

    def convert_for_autocorrection(self, delta_file):
        """

        """
        try:
            self.input_file = delta_file.split(" ")[0]
            content_list = []
            logger.info("Opening file: {}".format(self.input_file))
            with open(self.input_file, "r") as f:
                file_content = json.loads(f.read())

            # replace dist_name, existing_moc_dn and param_dict from distName, distName and parameters respectively
            for content in file_content:
                content = json.dumps(content)
                content = content.replace("dist_name", "distName")
                content = content.replace("existing_moc_dn", "distName")
                content = content.replace("param_dict", "parameters")
                content = json.loads(content)
                content_list.append(content)

            # replace operation value from upper case to lower case string
            # create a dict of param
            for content in content_list:
                content['operation'] = content['operation'].lower()
                param_list = []
                for info in content['parameters']:
                    if isinstance(content['parameters'][info], int):
                        info_value = str(content['parameters'][info])
                    else:
                        info_value = content['parameters'][info]
                    info_dict = {"operation": "update", "parameterName": info, "value": info_value}

                    param_list.append(info_dict)
                content['parameters'] = param_list
            local_exec_path = self.find_execution_path()
            self.ac_output_file = local_exec_path+'pre_autocorrected_'+self.input_file.split("/")[-1]
            logger.debug("writing output to {}".format(self.ac_output_file))
            with open(self.ac_output_file, "w") as f:
                f.write(json.dumps(content_list, indent=4))
        except Exception as ac_e:
            raise("failed to convert delta file: {}".format(ac_e))
        return self.ac_output_file

    def convert_for_netact(self, ac_input_file):
        """

        """
        with open(self.input_file, "r") as f:
            ref_file_content = json.loads(f.read())

        with open(ac_input_file, "r") as f:
            file_content = json.loads(f.read())

        # nidd_filename = "nidd_*.json"
        # local_nidd_path = "/home/ute/"
        # logger.debug("#### Find NIDD file")
        # output = subprocess.check_output('find {}{}'.format(local_nidd_path, nidd_filename), shell=True).decode('utf-8')
        # nidd_file_found = re.search(r'(nidd_[A-Z])\w+.json', output, re.DOTALL).group()
        # self.nidd_file = "{}{}".format(local_nidd_path, nidd_file_found)
        #
        # with open(self.nidd_file, "r") as f:
        #     nidd_content = json.loads(f.read())

        # find existing_moc_dn from input file
        existing_dn = [i['existing_moc_dn'] for i in ref_file_content if i.get('existing_moc_dn')]

        # replace operation value from lower case to upper case string
        # replace distName, distName and parameters from dist_name, existing_moc_dn and param_dict respectively
        # add updated meta release version
        # create dict of params from list of dict of params

        for content in file_content:

            content['operation'] = content['operation'].upper()

            param_dict = {}
            for dict_info in content['parameters']:
                dict_info_val = dict_info['value']
                if isinstance(dict_info['value'], str) and dict_info['value'].isnumeric():
                    dict_info_val = int(dict_info['value'])

                param_dict[dict_info['parameterName']] = dict_info_val

            content['param_dict'] = param_dict
            del content['parameters']
            if content['distName'] in existing_dn:
                content['existing_moc_dn'] = content['distName']
            else:
                content['dist_name'] = content['distName']
            del content['distName']
        self.nt_output_file = ac_input_file.replace("pre_autocorrected", "final")
        with open(self.nt_output_file, "w") as f:
            f.write(json.dumps(file_content, indent=4))
        return self.nt_output_file

    @staticmethod
    def find_execution_path():
        local_nidd_path = "execution_logs/"
        cur_path = subprocess.check_output('pwd', shell=True).decode('utf-8').strip()
        return cur_path+"/"+local_nidd_path

